  "Ativar/desativar efeito de audio": {"en": "Toggle audio effect", "es": "Activar/desactivar efecto de audio", "ar": "تفعيل/تعطيل تأثير الصوت", "ko": "오디오 효과 켜기/끄기", "ja": "音声エフェクトのオン/オフ", "zh": "启用/停用音频效果", "hi": "ऑडियो इफ़ेक्ट चालू/बंद करें", "id": "Aktifkan/nonaktifkan efek audio", "ru": "Включить/выключить аудиоэффект"},
  "Atras da pessoa": {"en": "Behind the person", "es": "Detrás de la persona", "ar": "خلف الشخص", "ko": "사람 뒤에", "ja": "人物の後ろ", "zh": "人物后方", "hi": "व्यक्ति के पीछे", "id": "Di belakang orang", "ru": "Позади человека"},
