  "Emissivo": {"en": "Emissive", "es": "Emisivo", "ar": "انبعاثي", "ko": "발광", "ja": "エミッシブ", "zh": "自发光", "hi": "एमिसिव", "id": "Emisif", "ru": "Свечение"},
  "Encaixar na grade": {"en": "Snap to grid", "es": "Ajustar a la cuadrícula", "ar": "محاذاة إلى الشبكة", "ko": "격자에 맞추기", "ja": "グリッドにスナップ", "zh": "吸附到网格", "hi": "ग्रिड पर स्नैप करें", "id": "Jepret ke kisi", "ru": "Привязка к сетке"},
  "Encurtar": {"en": "Shorten", "es": "Acortar", "ar": "تقصير", "ko": "줄이기", "ja": "短くする", "zh": "缩短", "hi": "छोटा करें", "id": "Perpendek", "ru": "Укоротить"},
  "Enquadrar": {"en": "Frame", "es": "Encuadrar", "ar": "تأطير", "ko": "화면에 맞추기", "ja": "画面に収める", "zh": "框显", "hi": "फ़्रेम करें", "id": "Pas ke layar", "ru": "Вписать"},
  "Enquadrar a cena": {"en": "Frame the scene", "es": "Encuadrar la escena", "ar": "تأطير المشهد", "ko": "장면을 화면에 맞추기", "ja": "シーンを画面に収める", "zh": "框显场景", "hi": "दृश्य को फ़्रेम करें", "id": "Pas adegan ke layar", "ru": "Вписать сцену"},
  "Enquadrar a cena inteira": {"en": "Frame the whole scene", "es": "Encuadrar toda la escena", "ar": "تأطير المشهد بأكمله", "ko": "전체 장면을 화면에 맞추기", "ja": "シーン全体を画面に収める", "zh": "框显整个场景", "hi": "पूरे दृश्य को फ़्रेम करें", "id": "Pas seluruh adegan ke layar", "ru": "Вписать всю сцену"},
  "Enquadrar o objeto selecionado": {"en": "Frame the selected object", "es": "Encuadrar el objeto seleccionado", "ar": "تأطير الكائن المحدد", "ko": "선택한 오브젝트를 화면에 맞추기", "ja": "選択したオブジェクトを画面に収める", "zh": "框显所选对象", "hi": "चयनित ऑब्जेक्ट को फ़्रेम करें", "id": "Pas objek terpilih ke layar", "ru": "Вписать выбранный объект"},
  "Enquadrar selecionado": {"en": "Frame selected", "es": "Encuadrar seleccionado", "ar": "تأطير المحدد", "ko": "선택 항목 화면에 맞추기", "ja": "選択物を画面に収める", "zh": "框显所选", "hi": "चयनित को फ़्रेम करें", "id": "Pas yang terpilih ke layar", "ru": "Вписать выбранное"},
  "Enquadrar seleção": {"en": "Frame selection", "es": "Encuadrar selección", "ar": "تأطير التحديد", "ko": "선택 영역 화면에 맞추기", "ja": "選択範囲を画面に収める", "zh": "框显选区", "hi": "चयन को फ़्रेम करें", "id": "Pas seleksi ke layar", "ru": "Вписать выделение"},
  "Enquadrar tudo": {"en": "Frame all", "es": "Encuadrar todo", "ar": "تأطير الكل", "ko": "모두 화면에 맞추기", "ja": "全体を画面に収める", "zh": "框显全部", "hi": "सब कुछ फ़्रेम करें", "id": "Pas semua ke layar", "ru": "Вписать всё"},
  "Entendi": {"en": "Got it", "es": "Entendido", "ar": "فهمت", "ko": "알겠어요", "ja": "わかりました", "zh": "知道了", "hi": "समझ गया", "id": "Mengerti", "ru": "Понятно"},
  "Entrar com Código": {"en": "Sign in with Code", "es": "Iniciar sesión con código", "ar": "تسجيل الدخول بالرمز", "ko": "코드로 로그인", "ja": "コードでログイン", "zh": "使用代码登录", "hi": "कोड से साइन इन करें", "id": "Masuk dengan Kode", "ru": "Войти по коду"},
  "Enviar": {"en": "Send", "es": "Enviar", "ar": "إرسال", "ko": "보내기", "ja": "送信", "zh": "发送", "hi": "भेजें", "id": "Kirim", "ru": "Отправить"},
  "Erro, sugestao de ferramenta ou de efeito — vai direto para o criador do app.": {"en": "Bug, tool or effect suggestion — goes straight to the app's creator.", "es": "Error, sugerencia de herramienta o de efecto — va directo al creador de la app.", "ar": "خطأ أو اقتراح أداة أو تأثير — يصل مباشرة إلى مطوّر التطبيق.", "ko": "오류, 도구나 효과 제안 — 앱 제작자에게 바로 전달됩니다.", "ja": "バグ、ツールやエフェクトの提案 — アプリの作者に直接届きます。", "zh": "错误、工具或效果建议 — 直接发送给应用的开发者。", "hi": "बग, टूल या इफ़ेक्ट का सुझाव — सीधे ऐप के निर्माता तक जाता है।", "id": "Bug, saran alat atau efek — langsung sampai ke pembuat aplikasi.", "ru": "Ошибка, идея инструмента или эффекта — попадёт прямо к создателю приложения."},
  "Escala do nulo -> espacamento/raio · Rotacao Z -> rotacao da grade · Rotacao Y -> twist.": {"en": "Null scale -> spacing/radius · Z rotation -> grid rotation · Y rotation -> twist.", "es": "Escala del nulo -> espaciado/radio · Rotación Z -> rotación de la cuadrícula · Rotación Y -> giro.", "ar": "مقياس الكائن الفارغ -> التباعد/نصف القطر · الدوران Z -> دوران الشبكة · الدوران Y -> الالتواء.", "ko": "널의 배율 -> 간격/반지름 · Z 회전 -> 격자 회전 · Y 회전 -> 비틀기.", "ja": "ヌルのスケール -> 間隔/半径 · Z回転 -> グリッドの回転 · Y回転 -> ツイスト。", "zh": "空对象缩放 -> 间距/半径 · Z旋转 -> 网格旋转 · Y旋转 -> 扭曲。", "hi": "नल का स्केल -> अंतर/त्रिज्या · Z घुमाव -> ग्रिड का घुमाव · Y घुमाव -> ट्विस्ट।", "id": "Skala null -> jarak/radius · Rotasi Z -> rotasi kisi · Rotasi Y -> puntiran.", "ru": "Масштаб нулевого объекта -> шаг/радиус · Вращение Z -> вращение сетки · Вращение Y -> скручивание."},
  "Escala/rotacao dele passam a modular a grade": {"en": "Its scale/rotation now modulate the grid", "es": "Su escala/rotación pasan a modular la cuadrícula", "ar": "يصبح مقياسه/دورانه متحكمًا في الشبكة", "ko": "이제 그 배율/회전이 격자를 조절합니다", "ja": "そのスケール/回転がグリッドを制御するようになります", "zh": "它的缩放/旋转将开始调控网格", "hi": "उसका स्केल/घुमाव अब ग्रिड को नियंत्रित करेगा", "id": "Skala/rotasinya kini memodulasi kisi", "ru": "Его масштаб/вращение теперь управляют сеткой"},
  "Escalonar selecao": {"en": "Stagger selection", "es": "Escalonar selección", "ar": "تدريج التحديد", "ko": "선택 항목 시차 배치", "ja": "選択範囲をずらして配置", "zh": "错开所选", "hi": "चयन को क्रमबद्ध करें", "id": "Susun seleksi berjenjang", "ru": "Расставить выделенное каскадом"},
  "Escolha Mover, Girar ou Escalar para ajustar": {"en": "Choose Move, Rotate or Scale to adjust", "es": "Elige Mover, Girar o Escalar para ajustar", "ar": "اختر تحريك أو تدوير أو تحجيم للضبط", "ko": "이동, 회전 또는 크기 조절을 선택해 조정하세요", "ja": "移動、回転、拡大・縮小のいずれかを選んで調整します", "zh": "选择移动、旋转或缩放来调整", "hi": "समायोजित करने के लिए खिसकाएँ, घुमाएँ या स्केल चुनें", "id": "Pilih Pindahkan, Putar, atau Skalakan untuk menyesuaikan", "ru": "Выберите Переместить, Повернуть или Масштабировать, чтобы настроить"},
  "Escolha o estilo": {"en": "Choose the style", "es": "Elige el estilo", "ar": "اختر النمط", "ko": "스타일 선택", "ja": "スタイルを選択", "zh": "选择样式", "hi": "स्टाइल चुनें", "id": "Pilih gaya", "ru": "Выберите стиль"},
  "Escolha uma foto ou vídeo. A IA ESRGAN amplia detalhes no aparelho, sem enviar sua mídia. Use 2× para arquivos menores ou 4× para ampliar mais.\n\nOs CCs mudam as cores: escolha um visual e ajuste a intensidade. Reduzir ruído suaviza granulação; Detalhes realça bordas.\n\nComparar processa uma imagem ou o primeiro quadro do vídeo. Gerar resultado processa tudo. Vídeos são salvos a 30 fps com o áudio original, recodificado. O tempo depende do arquivo e do celular.\n\nA IA pode alterar texturas; compare antes de salvar. O original permanece intacto.": {"en": "Choose a photo or video. The ESRGAN AI upscales details on the device, without uploading your media. Use 2× for smaller files or 4× to enlarge more.\n\nThe CCs change the colors: pick a look and adjust the intensity. Reduce noise smooths grain; Details sharpens edges.\n\nCompare processes one image or the first frame of the video. Generate result processes everything. Videos are saved at 30 fps with the original audio, re-encoded. The time depends on the file and the phone.\n\nThe AI may alter textures; compare before saving. The original stays intact.", "es": "Elige una foto o un vídeo. La IA ESRGAN amplía los detalles en el dispositivo, sin enviar tu contenido. Usa 2× para archivos más pequeños o 4× para ampliar más.\n\nLos CCs cambian los colores: elige un estilo y ajusta la intensidad. Reducir ruido suaviza el grano; Detalles realza los bordes.\n\nComparar procesa una imagen o el primer fotograma del vídeo. Generar resultado lo procesa todo. Los vídeos se guardan a 30 fps con el audio original, recodificado. El tiempo depende del archivo y del móvil.\n\nLa IA puede alterar texturas; compara antes de guardar. El original permanece intacto.", "ar": "اختر صورة أو فيديو. يقوم الذكاء الاصطناعي ESRGAN بتكبير التفاصيل على الجهاز دون إرسال وسائطك. استخدم 2× للملفات الأصغر أو 4× لتكبير أكبر.\n\nتغيّر CCs الألوان: اختر مظهرًا واضبط الشدة. تقليل التشويش ينعّم الحبيبات؛ التفاصيل تبرز الحواف.\n\nالمقارنة تعالج صورة واحدة أو الإطار الأول من الفيديو. إنشاء النتيجة يعالج كل شيء. تُحفظ مقاطع الفيديو بمعدل 30 fps مع الصوت الأصلي معاد الترميز. يعتمد الوقت على الملف والهاتف.\n\nقد يغيّر الذكاء الاصطناعي الملمس؛ قارن قبل الحفظ. يبقى الأصل سليمًا.", "ko": "사진이나 동영상을 선택하세요. ESRGAN AI가 미디어를 전송하지 않고 기기에서 디테일을 확대합니다. 파일을 작게 하려면 2×, 더 크게 확대하려면 4×를 사용하세요.\n\nCC는 색상을 바꿉니다. 원하는 룩을 고르고 강도를 조절하세요. 노이즈 감소는 입자를 부드럽게 하고, 디테일은 가장자리를 또렷하게 합니다.\n\n비교는 이미지 한 장 또는 동영상의 첫 프레임을 처리합니다. 결과 생성은 전체를 처리합니다. 동영상은 원본 오디오를 다시 인코딩해 30 fps로 저장됩니다. 소요 시간은 파일과 휴대폰에 따라 다릅니다.\n\nAI가 질감을 바꿀 수 있으니 저장하기 전에 비교하세요. 원본은 그대로 유지됩니다.", "ja": "写真または動画を選択します。ESRGAN AIがメディアを送信せず、端末上でディテールを拡大します。ファイルを小さくしたい場合は2×、もっと拡大したい場合は4×を使います。\n\nCCは色を変えます。ルックを選んで強度を調整してください。ノイズを低減は粒状感を滑らかにし、詳細はエッジを強調します。\n\n比較は画像1枚または動画の最初のフレームを処理します。結果を生成はすべてを処理します。動画は元の音声を再エンコードして30 fpsで保存されます。所要時間はファイルと端末によって異なります。\n\nAIは質感を変えることがあります。保存する前に比較してください。元のファイルはそのまま残ります。", "zh": "选择一张照片或一段视频。ESRGAN AI 在设备上放大细节，不会上传你的媒体。文件较小时用 2×，想放大更多用 4×。\n\nCC 用于改变颜色：选择一种风格并调节强度。降噪可平滑颗粒；细节可锐化边缘。\n\n对比只处理一张图片或视频的第一帧。生成结果会处理全部内容。视频以 30 fps 保存，并保留重新编码后的原始音频。耗时取决于文件和手机。\n\nAI 可能改变纹理；保存前请先对比。原文件保持不变。", "hi": "एक फ़ोटो या वीडियो चुनें। ESRGAN AI आपकी मीडिया भेजे बिना डिवाइस पर ही विवरण बढ़ाता है। छोटी फ़ाइलों के लिए 2× या और बड़ा करने के लिए 4× इस्तेमाल करें।\n\nCC रंग बदलते हैं: एक लुक चुनें और तीव्रता समायोजित करें। शोर कम करें दानेदारपन को नरम करता है; विवरण किनारों को उभारता है।\n\nतुलना एक छवि या वीडियो के पहले फ़्रेम को प्रोसेस करती है। परिणाम बनाएँ सब कुछ प्रोसेस करता है। वीडियो मूल ऑडियो के साथ, फिर से एन्कोड करके, 30 fps पर सहेजे जाते हैं। समय फ़ाइल और फ़ोन पर निर्भर करता है।\n\nAI बनावट बदल सकता है; सहेजने से पहले तुलना करें। मूल फ़ाइल जैसी की तैसी रहती है।", "id": "Pilih foto atau video. AI ESRGAN memperbesar detail di perangkat, tanpa mengirim media Anda. Gunakan 2× untuk berkas yang lebih kecil atau 4× untuk memperbesar lebih jauh.\n\nCC mengubah warna: pilih tampilan dan atur intensitasnya. Kurangi derau menghaluskan butiran; Detail mempertajam tepi.\n\nBandingkan memproses satu gambar atau bingkai pertama video. Buat hasil memproses semuanya. Video disimpan pada 30 fps dengan audio asli yang dienkode ulang. Lamanya tergantung berkas dan ponsel.\n\nAI dapat mengubah tekstur; bandingkan sebelum menyimpan. Berkas asli tetap utuh.", "ru": "Выберите фото или видео. ИИ ESRGAN увеличивает детали прямо на устройстве, не отправляя ваши файлы. Используйте 2× для файлов поменьше или 4× для большего увеличения.\n\nCC меняют цвета: выберите образ и настройте интенсивность. Уменьшить шум сглаживает зерно; Детали подчёркивают края.\n\nСравнить обрабатывает одно изображение или первый кадр видео. Создать результат обрабатывает всё. Видео сохраняются с частотой 30 fps и исходным звуком, перекодированным. Время зависит от файла и телефона.\n\nИИ может менять текстуры; сравните перед сохранением. Оригинал остаётся нетронутым."},
  "Escolha uma parte, avance o tempo e ajuste a pose. Cada ajuste grava um keyframe. O rig importado deforma a malha pelos pesos dos ossos.": {"en": "Choose a part, move the time forward and adjust the pose. Each adjustment records a keyframe. The imported rig deforms the mesh through the bone weights.", "es": "Elige una parte, avanza el tiempo y ajusta la pose. Cada ajuste graba un fotograma clave. El rig importado deforma la malla mediante los pesos de los huesos.", "ar": "اختر جزءًا، وقدّم الوقت، واضبط الوضعية. كل تعديل يسجّل إطارًا مفتاحيًا. الهيكل المستورد يشوّه الشبكة وفق أوزان العظام.", "ko": "부위를 선택하고 시간을 앞으로 옮긴 뒤 포즈를 조정하세요. 조정할 때마다 키프레임이 기록됩니다. 가져온 리그는 본 가중치로 메시를 변형합니다.", "ja": "パーツを選び、時間を進めてポーズを調整します。調整するたびにキーフレームが記録されます。読み込んだリグはボーンのウェイトでメッシュを変形します。", "zh": "选择一个部位，推进时间并调整姿势。每次调整都会记录一个关键帧。导入的绑定通过骨骼权重使网格变形。", "hi": "एक हिस्सा चुनें, समय आगे बढ़ाएँ और पोज़ समायोजित करें। हर समायोजन एक कीफ़्रेम दर्ज करता है। आयातित रिग हड्डियों के वज़न से मेश को विकृत करता है।", "id": "Pilih satu bagian, majukan waktu, lalu atur posenya. Setiap penyesuaian merekam satu keyframe. Rig yang diimpor mengubah bentuk mesh lewat bobot tulang.", "ru": "Выберите часть, продвиньте время и настройте позу. Каждая правка записывает ключевой кадр. Импортированный риг деформирует сетку по весам костей."},
  "Escolher": {"en": "Choose", "es": "Elegir", "ar": "اختيار", "ko": "선택", "ja": "選択", "zh": "选择", "hi": "चुनें", "id": "Pilih", "ru": "Выбрать"},
  "Escolher outro estilo": {"en": "Choose another style", "es": "Elegir otro estilo", "ar": "اختيار نمط آخر", "ko": "다른 스타일 선택", "ja": "別のスタイルを選択", "zh": "选择其他样式", "hi": "दूसरा स्टाइल चुनें", "id": "Pilih gaya lain", "ru": "Выбрать другой стиль"},
  "Escolher qualquer cor": {"en": "Choose any color", "es": "Elegir cualquier color", "ar": "اختيار أي لون", "ko": "원하는 색상 선택", "ja": "好きな色を選択", "zh": "选择任意颜色", "hi": "कोई भी रंग चुनें", "id": "Pilih warna apa pun", "ru": "Выбрать любой цвет"},
  "Escolher video": {"en": "Choose video", "es": "Elegir vídeo", "ar": "اختيار فيديو", "ko": "동영상 선택", "ja": "動画を選択", "zh": "选择视频", "hi": "वीडियो चुनें", "id": "Pilih video", "ru": "Выбрать видео"},
  "Escreva o texto": {"en": "Type the text", "es": "Escribe el texto", "ar": "اكتب النص", "ko": "텍스트를 입력하세요", "ja": "テキストを入力", "zh": "输入文本", "hi": "टेक्स्ट लिखें", "id": "Tulis teksnya", "ru": "Введите текст"},
  "Espaco": {"en": "Spacing", "es": "Espaciado", "ar": "التباعد", "ko": "간격", "ja": "間隔", "zh": "间距", "hi": "अंतर", "id": "Jarak", "ru": "Интервал"},
  "Espaco exato": {"en": "Exact spacing", "es": "Espaciado exacto", "ar": "تباعد دقيق", "ko": "정확한 간격", "ja": "正確な間隔", "zh": "精确间距", "hi": "सटीक अंतर", "id": "Jarak tepat", "ru": "Точный интервал"},
  "Espessura": {"en": "Thickness", "es": "Grosor", "ar": "السماكة", "ko": "두께", "ja": "太さ", "zh": "粗细", "hi": "मोटाई", "id": "Ketebalan", "ru": "Толщина"},
  "ESRGAN • processamento no aparelho": {"en": "ESRGAN • on-device processing", "es": "ESRGAN • procesamiento en el dispositivo", "ar": "ESRGAN • معالجة على الجهاز", "ko": "ESRGAN • 기기 내 처리", "ja": "ESRGAN • 端末内で処理", "zh": "ESRGAN • 设备端处理", "hi": "ESRGAN • डिवाइस पर प्रोसेसिंग", "id": "ESRGAN • pemrosesan di perangkat", "ru": "ESRGAN • обработка на устройстве"},
  "Esta camada nao tem cor editavel.": {"en": "This layer has no editable color.", "es": "Esta capa no tiene color editable.", "ar": "هذه الطبقة ليس لها لون قابل للتعديل.", "ko": "이 레이어에는 편집할 수 있는 색상이 없습니다.", "ja": "このレイヤーには編集できる色がありません。", "zh": "此图层没有可编辑的颜色。", "hi": "इस लेयर में संपादन योग्य रंग नहीं है।", "id": "Lapisan ini tidak punya warna yang bisa diedit.", "ru": "У этого слоя нет редактируемого цвета."},
  "Esta camada nao tem forma parametrica para ajustar.": {"en": "This layer has no parametric shape to adjust.", "es": "Esta capa no tiene una forma paramétrica que ajustar.", "ar": "هذه الطبقة ليس لها شكل بارامتري لضبطه.", "ko": "이 레이어에는 조정할 수 있는 파라메트릭 도형이 없습니다.", "ja": "このレイヤーには調整できるパラメトリックシェイプがありません。", "zh": "此图层没有可调整的参数化形状。", "hi": "इस लेयर में समायोजित करने के लिए पैरामीट्रिक आकार नहीं है।", "id": "Lapisan ini tidak punya bentuk parametrik untuk diatur.", "ru": "У этого слоя нет параметрической фигуры для настройки."},
  "Esta forma e um caminho desenhado (sem parametros). Converta para editar Tamanho, Arredondamento, Pontas e afins — animaveis.": {"en": "This shape is a drawn path (no parameters). Convert it to edit Size, Roundness, Points and the like — animatable.", "es": "Esta forma es un trazado dibujado (sin parámetros). Conviértela para editar Tamaño, Redondeo, Puntas y similares — animables.", "ar": "هذا الشكل مسار مرسوم (بلا معاملات). حوّله لتعديل الحجم والاستدارة والرؤوس وما شابه — وكلها قابلة للتحريك.", "ko": "이 도형은 그린 경로입니다(매개변수 없음). 변환하면 크기, 둥글기, 꼭짓점 등을 편집할 수 있습니다 — 애니메이션 가능.", "ja": "このシェイプは描画したパスです（パラメータなし）。変換すると、サイズ、丸み、頂点などを編集できます — アニメーション可能。", "zh": "此形状是绘制的路径（无参数）。转换后可编辑大小、圆角、顶点等 — 均可制作动画。", "hi": "यह आकार एक बनाया हुआ पाथ है (बिना पैरामीटर)। आकार, गोलाई, कोने आदि संपादित करने के लिए इसे बदलें — ये एनिमेट हो सकते हैं।", "id": "Bentuk ini adalah jalur yang digambar (tanpa parameter). Konversi untuk mengedit Ukuran, Kebulatan, Ujung, dan sejenisnya — bisa dianimasikan.", "ru": "Эта фигура — нарисованный путь (без параметров). Преобразуйте её, чтобы редактировать Размер, Скругление, Вершины и подобное — с анимацией."},
  "Esta forma nao tem esse numero": {"en": "This shape doesn't have that number", "es": "Esta forma no tiene ese número", "ar": "هذا الشكل ليس له هذا الرقم", "ko": "이 도형에는 그 숫자가 없습니다", "ja": "このシェイプにはその数値がありません", "zh": "此形状没有该数值", "hi": "इस आकार में वह संख्या नहीं है", "id": "Bentuk ini tidak punya angka tersebut", "ru": "У этой фигуры нет такого числа"},
  "Esta legenda foi gerada em frases. O destaque precisa do tempo por palavra — gere de novo no modo Palavra por palavra.": {"en": "These captions were generated as sentences. Highlighting needs per-word timing — generate again in Word by word mode.", "es": "Estos subtítulos se generaron por frases. El resaltado necesita el tiempo por palabra — genéralos de nuevo en el modo Palabra por palabra.", "ar": "تم إنشاء هذه الترجمة على شكل جمل. يحتاج التمييز إلى توقيت لكل كلمة — أعد الإنشاء في وضع كلمة بكلمة.", "ko": "이 자막은 문장 단위로 생성되었습니다. 강조에는 단어별 시간이 필요합니다 — 단어별 모드로 다시 생성하세요.", "ja": "この字幕は文単位で生成されています。ハイライトには単語ごとのタイミングが必要です — 単語ごとモードで再生成してください。", "zh": "此字幕按句子生成。高亮需要逐词时间 — 请在逐词模式下重新生成。", "hi": "यह कैप्शन वाक्यों में बनाया गया था। हाइलाइट के लिए हर शब्द का समय चाहिए — शब्द-दर-शब्द मोड में फिर से बनाएँ।", "id": "Subtitel ini dibuat per kalimat. Sorotan membutuhkan waktu per kata — buat ulang dalam mode Kata per kata.", "ru": "Эти субтитры созданы по фразам. Для подсветки нужно время каждого слова — создайте заново в режиме Слово за словом."},
  "Esta propriedade precisa de 2 ou mais keyframes para ter loop.": {"en": "This property needs 2 or more keyframes to loop.", "es": "Esta propiedad necesita 2 o más fotogramas clave para tener bucle.", "ar": "تحتاج هذه الخاصية إلى 2 أو أكثر من الإطارات المفتاحية لتكرارها.", "ko": "이 속성을 반복하려면 키프레임이 2개 이상 필요합니다.", "ja": "このプロパティをループさせるには2つ以上のキーフレームが必要です。", "zh": "此属性需要 2 个或更多关键帧才能循环。", "hi": "लूप के लिए इस प्रॉपर्टी में 2 या अधिक कीफ़्रेम चाहिए।", "id": "Properti ini membutuhkan 2 keyframe atau lebih untuk bisa diulang.", "ru": "Для зацикливания этому свойству нужно 2 или больше ключевых кадров."},
  "Esta transicao precisa de quadros alem do corte. Encurte a transicao ou congele as pontas.": {"en": "This transition needs frames beyond the cut. Shorten the transition or freeze the ends.", "es": "Esta transición necesita fotogramas más allá del corte. Acorta la transición o congela los extremos.", "ar": "يحتاج هذا الانتقال إلى إطارات تتجاوز القطع. قصّر الانتقال أو جمّد الطرفين.", "ko": "이 전환에는 컷 너머의 프레임이 필요합니다. 전환을 줄이거나 양 끝을 고정하세요.", "ja": "このトランジションにはカットの先のフレームが必要です。トランジションを短くするか、両端をフリーズしてください。", "zh": "此转场需要剪切点之外的帧。请缩短转场或冻结两端。", "hi": "इस ट्रांज़िशन को कट से आगे के फ़्रेम चाहिए। ट्रांज़िशन छोटा करें या सिरों को फ़्रीज़ करें।", "id": "Transisi ini membutuhkan bingkai di luar potongan. Perpendek transisinya atau bekukan ujung-ujungnya.", "ru": "Этому переходу нужны кадры за пределами среза. Укоротите переход или заморозьте концы."},
  "Estabilizar": {"en": "Stabilize", "es": "Estabilizar", "ar": "تثبيت", "ko": "안정화", "ja": "スタビライズ", "zh": "防抖", "hi": "स्थिर करें", "id": "Stabilkan", "ru": "Стабилизировать"},
  "Este aparelho esta desenhando a cena no pintor em CPU: sem sombra nem brilho, e bem mais lento.": {"en": "This device is drawing the scene with the CPU painter: no shadows or glow, and much slower.", "es": "Este dispositivo está dibujando la escena con el pintor en CPU: sin sombra ni brillo, y mucho más lento.", "ar": "يرسم هذا الجهاز المشهد بالراسم على CPU: بلا ظلال ولا توهج، وأبطأ بكثير.", "ko": "이 기기는 CPU 페인터로 장면을 그리고 있습니다. 그림자와 광택이 없고 훨씬 느립니다.", "ja": "この端末はCPUペインターでシーンを描画しています。影や光沢がなく、かなり遅くなります。", "zh": "此设备正在用 CPU 绘制器绘制场景：没有阴影和光泽，而且慢得多。", "hi": "यह डिवाइस दृश्य को CPU पेंटर से बना रहा है: न छाया, न चमक, और काफ़ी धीमा।", "id": "Perangkat ini menggambar adegan dengan pelukis CPU: tanpa bayangan maupun kilau, dan jauh lebih lambat.", "ru": "Это устройство рисует сцену CPU-отрисовщиком: без теней и бликов, и намного медленнее."},
  "Este apelido é único e assinará seus vídeos e templates no mural.": {"en": "This nickname is unique and will sign your videos and templates on the board.", "es": "Este apodo es único y firmará tus vídeos y plantillas en el mural.", "ar": "هذا الاسم المستعار فريد وسيوقّع مقاطعك وقوالبك على اللوحة.", "ko": "이 닉네임은 고유하며 게시판에 올린 동영상과 템플릿에 서명으로 표시됩니다.", "ja": "このニックネームは一意で、掲示板に投稿する動画やテンプレートの署名になります。", "zh": "此昵称是唯一的，将作为你在社区墙上视频和模板的署名。", "hi": "यह उपनाम अद्वितीय है और बोर्ड पर आपके वीडियो और टेम्पलेट पर आपके नाम के रूप में दिखेगा।", "id": "Nama panggilan ini unik dan akan menandai video serta template Anda di papan.", "ru": "Этот никнейм уникален и будет подписью к вашим видео и шаблонам на стене."},
