  "Nome da camera": {"en": "Camera name", "es": "Nombre de la cámara", "ar": "اسم الكاميرا", "ko": "카메라 이름", "ja": "カメラ名", "zh": "摄像机名称", "hi": "कैमरे का नाम", "id": "Nama kamera", "ru": "Название камеры"},
