  "Nova camera (enquadramento atual)": {"en": "New camera (current framing)", "es": "Nueva cámara (encuadre actual)", "ar": "كاميرا جديدة (الإطار الحالي)", "ko": "새 카메라 (현재 구도)", "ja": "新規カメラ（現在の構図）", "zh": "新建摄像机（当前取景）", "hi": "नया कैमरा (मौजूदा फ़्रेमिंग)", "id": "Kamera baru (pembingkaian saat ini)", "ru": "Новая камера (текущее кадрирование)"},
  "Nova luz": {"en": "New light", "es": "Nueva luz", "ar": "ضوء جديد", "ko": "새 조명", "ja": "新規ライト", "zh": "新建灯光", "hi": "नया प्रकाश", "id": "Cahaya baru", "ru": "Новый источник света"},
  "Nova recriacao · Codex": {"en": "New recreation · Codex", "es": "Nueva recreación · Codex", "ar": "إعادة إنشاء جديدة · Codex", "ko": "새 재현 · Codex", "ja": "新しい再現 · Codex", "zh": "新重制 · Codex", "hi": "नई पुनर्रचना · Codex", "id": "Rekreasi baru · Codex", "ru": "Новое воссоздание · Codex"},
