  "Objeto 3D": {"en": "3D object", "es": "Objeto 3D", "ar": "كائن ثلاثي الأبعاد", "ko": "3D 오브젝트", "ja": "3Dオブジェクト", "zh": "3D对象", "hi": "3D ऑब्जेक्ट", "id": "Objek 3D", "ru": "3D-объект"},
  "Objeto bloqueado. Desbloqueie na cena para editar.": {"en": "Object locked. Unlock it in the scene to edit.", "es": "Objeto bloqueado. Desbloquéalo en la escena para editarlo.", "ar": "الكائن مقفل. ألغِ قفله في المشهد لتعديله.", "ko": "오브젝트가 잠겨 있습니다. 편집하려면 장면에서 잠금을 해제하세요.", "ja": "オブジェクトはロックされています。編集するにはシーンでロックを解除してください。", "zh": "对象已锁定。请在场景中解锁后再编辑。", "hi": "ऑब्जेक्ट लॉक है। संपादित करने के लिए दृश्य में अनलॉक करें।", "id": "Objek terkunci. Buka kuncinya di adegan untuk mengedit.", "ru": "Объект заблокирован. Разблокируйте его в сцене, чтобы редактировать."},
  "Objetos, luzes e cameras": {"en": "Objects, lights and cameras", "es": "Objetos, luces y cámaras", "ar": "الكائنات والأضواء والكاميرات", "ko": "오브젝트, 조명 및 카메라", "ja": "オブジェクト、ライト、カメラ", "zh": "对象、灯光和摄像机", "hi": "ऑब्जेक्ट, प्रकाश और कैमरे", "id": "Objek, cahaya, dan kamera", "ru": "Объекты, источники света и камеры"},
