  "Oclusao": {"en": "Occlusion", "es": "Oclusión", "ar": "الإطباق", "ko": "오클루전", "ja": "オクルージョン", "zh": "遮蔽", "hi": "ऑक्लूज़न", "id": "Oklusi", "ru": "Окклюзия"},
