  "Olhar para…": {"en": "Look at…", "es": "Mirar a…", "ar": "النظر إلى…", "ko": "바라보기…", "ja": "注視…", "zh": "注视…", "hi": "लुक ऐट…", "id": "Lihat ke…", "ru": "Смотреть на…"},
  "Onde a neblina comeca": {"en": "Where the fog starts", "es": "Dónde empieza la niebla", "ar": "حيث يبدأ الضباب", "ko": "안개가 시작되는 지점", "ja": "霧が始まる位置", "zh": "雾开始的位置", "hi": "कोहरा कहाँ से शुरू होता है", "id": "Tempat kabut mulai", "ru": "Где начинается туман"},
