  "Tirar": {"en": "Remove", "es": "Quitar", "ar": "إزالة", "ko": "제거", "ja": "削除", "zh": "移除", "hi": "हटाएँ", "id": "Hapus", "ru": "Убрать"},
  "Tirar traco": {"en": "Remove stroke", "es": "Quitar trazo", "ar": "إزالة الحد", "ko": "선 제거", "ja": "線を削除", "zh": "移除描边", "hi": "स्ट्रोक हटाएँ", "id": "Hapus goresan", "ru": "Убрать обводку"},
