  "O escuro": {"en": "Dark areas", "es": "Lo oscuro", "ar": "المناطق الداكنة", "ko": "어두운 부분", "ja": "暗い部分", "zh": "暗部", "hi": "गहरे हिस्से", "id": "Bagian gelap", "ru": "Тёмное"},
  "O mural não devolveu o endereço da mídia.": {"en": "The board didn't return the media address.", "es": "El muro no devolvió la dirección del archivo multimedia.", "ar": "لم تُرجع اللوحة عنوان الوسائط.", "ko": "게시판이 미디어 주소를 반환하지 않았습니다.", "ja": "掲示板がメディアのアドレスを返しませんでした。", "zh": "社区墙未返回媒体地址。", "hi": "बोर्ड ने मीडिया का पता नहीं लौटाया।", "id": "Papan tidak mengembalikan alamat media.", "ru": "Доска не вернула адрес медиафайла."},
  "O padrão: bom resultado sem esperar demais.": {"en": "The default: good results without waiting too long.", "es": "El predeterminado: buen resultado sin esperar demasiado.", "ar": "الافتراضي: نتيجة جيدة دون انتظار طويل.", "ko": "기본값: 오래 기다리지 않고 좋은 결과.", "ja": "標準：待ちすぎずに良い結果。", "zh": "默认：效果好，无需久等。", "hi": "डिफ़ॉल्ट: ज़्यादा इंतज़ार किए बिना अच्छा नतीजा।", "id": "Bawaan: hasil bagus tanpa menunggu terlalu lama.", "ru": "По умолчанию: хороший результат без долгого ожидания."},
