  "Quicar por letra": {"en": "Bounce by letter", "es": "Rebote por letra", "ar": "ارتداد لكل حرف", "ko": "글자별 바운스", "ja": "文字ごとにバウンス", "zh": "逐字弹跳", "hi": "अक्षर दर अक्षर बाउंस", "id": "Pantul per huruf", "ru": "Отскок по буквам"},
  "Quicar por palavra": {"en": "Bounce by word", "es": "Rebote por palabra", "ar": "ارتداد لكل كلمة", "ko": "단어별 바운스", "ja": "単語ごとにバウンス", "zh": "逐词弹跳", "hi": "शब्द दर शब्द बाउंस", "id": "Pantul per kata", "ru": "Отскок по словам"},
  "R / B": {"en": "R / B", "es": "R / B", "ar": "R / B", "ko": "R / B", "ja": "R / B", "zh": "R / B", "hi": "R / B", "id": "R / B", "ru": "R / B"},
  "R / G": {"en": "R / G", "es": "R / G", "ar": "R / G", "ko": "R / G", "ja": "R / G", "zh": "R / G", "hi": "R / G", "id": "R / G", "ru": "R / G"},
  "Rachadura": {"en": "Crack", "es": "Grieta", "ar": "شق", "ko": "균열", "ja": "ひび割れ", "zh": "裂纹", "hi": "दरार", "id": "Retakan", "ru": "Трещина"},
  "Radial Blur": {"en": "Radial Blur", "es": "Desenfoque radial", "ar": "تمويه شعاعي", "ko": "방사형 흐림", "ja": "放射状ブラー", "zh": "径向模糊", "hi": "रेडियल ब्लर", "id": "Radial Blur", "ru": "Радиальное размытие"},
  "radial blur": {"en": "radial blur", "es": "desenfoque radial", "ar": "تمويه شعاعي", "ko": "방사형 흐림", "ja": "放射状ブラー", "zh": "径向模糊", "hi": "रेडियल ब्लर", "id": "radial blur", "ru": "радиальное размытие"},
  "Raio externo": {"en": "Outer radius", "es": "Radio exterior", "ar": "نصف القطر الخارجي", "ko": "외부 반경", "ja": "外側の半径", "zh": "外半径", "hi": "बाहरी त्रिज्या", "id": "Radius luar", "ru": "Внешний радиус"},
  "Raio interno": {"en": "Inner radius", "es": "Radio interior", "ar": "نصف القطر الداخلي", "ko": "내부 반경", "ja": "内側の半径", "zh": "内半径", "hi": "भीतरी त्रिज्या", "id": "Radius dalam", "ru": "Внутренний радиус"},
  "Rampa": {"en": "Wedge", "es": "Cuña", "ar": "إسفين", "ko": "쐐기", "ja": "くさび", "zh": "楔形", "hi": "वेज", "id": "Baji", "ru": "Клин"},
  "Random": {"en": "Random", "es": "Aleatorio", "ar": "عشوائي", "ko": "무작위", "ja": "ランダム", "zh": "随机", "hi": "रैंडम", "id": "Acak", "ru": "Случайный"},
  "Rapida": {"en": "Fast", "es": "Rápida", "ar": "سريعة", "ko": "빠름", "ja": "高速", "zh": "快速", "hi": "तेज़", "id": "Cepat", "ru": "Быстрое"},
  "Raw Values": {"en": "Raw Values", "es": "Valores brutos", "ar": "القيم الخام", "ko": "원시 값", "ja": "生の値", "zh": "原始值", "hi": "कच्चे मान", "id": "Nilai mentah", "ru": "Исходные значения"},
  "Reamostra a animação da camada em vários instantes. Mais amostras melhoram o rastro, mas aumentam o trabalho de renderização.": {"en": "Resamples the layer's animation at several instants. More samples improve the trail but increase rendering work.", "es": "Vuelve a muestrear la animación de la capa en varios instantes. Más muestras mejoran la estela, pero aumentan el trabajo de renderizado.", "ar": "يعيد أخذ عينات من حركة الطبقة في عدة لحظات. المزيد من العينات يحسّن الأثر، لكنه يزيد عمل العرض.", "ko": "레이어의 애니메이션을 여러 시점에서 다시 샘플링합니다. 샘플이 많을수록 잔상이 좋아지지만 렌더링 작업이 늘어납니다.", "ja": "レイヤーのアニメーションを複数の時点で再サンプリングします。サンプルを増やすと軌跡は良くなりますが、レンダリングの負荷が増えます。", "zh": "在多个时刻对图层动画重新采样。采样越多，拖尾越好，但渲染工作量也越大。", "hi": "लेयर के एनिमेशन को कई क्षणों पर फिर से सैंपल करता है। ज़्यादा सैंपल से ट्रेल बेहतर होती है, लेकिन रेंडरिंग का काम बढ़ जाता है।", "id": "Mengambil sampel ulang animasi lapisan di beberapa momen. Lebih banyak sampel memperbaiki jejak, tetapi menambah beban render.", "ru": "Пересэмплирует анимацию слоя в нескольких моментах времени. Больше сэмплов улучшают след, но увеличивают объём рендеринга."},
  "Reamostra a camada em instantes anteriores. Ecos define as cópias; intervalo separa os instantes; decaimento enfraquece o rastro. O comportamento temporal não é uma equivalência exata ao Echo da Adobe.": {"en": "Resamples the layer at earlier instants. Echoes sets the copies; interval spaces the instants; decay weakens the trail. The temporal behavior is not an exact equivalent of Adobe's Echo.", "es": "Vuelve a muestrear la capa en instantes anteriores. Ecos define las copias; intervalo separa los instantes; decaimiento debilita la estela. El comportamiento temporal no es una equivalencia exacta del Echo de Adobe.", "ar": "يعيد أخذ عينات من الطبقة في لحظات سابقة. الأصداء تحدد النسخ؛ الفاصل يباعد بين اللحظات؛ الاضمحلال يُضعف الأثر. السلوك الزمني ليس مطابقًا تمامًا لتأثير Echo من Adobe.", "ko": "레이어를 이전 시점에서 다시 샘플링합니다. 에코는 복사본 수를, 간격은 시점 사이의 거리를, 감쇠는 잔상이 약해지는 정도를 정합니다. 시간 동작은 Adobe의 Echo와 정확히 같지는 않습니다.", "ja": "レイヤーを過去の時点で再サンプリングします。エコーはコピー数、間隔は時点の間隔、減衰は軌跡の弱まり方を決めます。時間的な挙動は Adobe の Echo と完全に同じではありません。", "zh": "在更早的时刻对图层重新采样。回声决定副本数量；间隔拉开各时刻；衰减削弱拖尾。其时间行为并非 Adobe 的 Echo 的精确等价。", "hi": "लेयर को पहले के क्षणों पर फिर से सैंपल करता है। इको प्रतियाँ तय करता है; अंतराल क्षणों को अलग करता है; क्षय ट्रेल को कमज़ोर करता है। समय संबंधी व्यवहार Adobe के Echo के बिल्कुल बराबर नहीं है।", "id": "Mengambil sampel ulang lapisan di momen-momen sebelumnya. Gema menentukan jumlah salinan; interval memisahkan momen; peluruhan melemahkan jejak. Perilaku temporalnya bukan padanan persis dari Echo milik Adobe.", "ru": "Пересэмплирует слой в предыдущие моменты времени. Эхо задаёт число копий; интервал разделяет моменты; затухание ослабляет след. Временное поведение не является точным эквивалентом Echo от Adobe."},
  "recorte por cor": {"en": "color key", "es": "recorte por color", "ar": "قص حسب اللون", "ko": "색상 키", "ja": "カラーキー", "zh": "颜色抠像", "hi": "कलर की", "id": "kunci warna", "ru": "цветовой ключ"},
  "Reduz a imagem a blocos de cor. Mais blocos dão um mosaico fino; menos blocos deixam pixels grandes.": {"en": "Reduces the image to blocks of color. More blocks give a fine mosaic; fewer blocks leave large pixels.", "es": "Reduce la imagen a bloques de color. Más bloques dan un mosaico fino; menos bloques dejan píxeles grandes.", "ar": "يختزل الصورة إلى كتل لونية. المزيد من الكتل يعطي فسيفساء دقيقة؛ كتل أقل تترك بكسلات كبيرة.", "ko": "이미지를 색상 블록으로 줄입니다. 블록이 많으면 모자이크가 미세해지고, 적으면 픽셀이 커집니다.", "ja": "画像を色のブロックに落とし込みます。ブロックを増やすと細かいモザイクに、減らすと大きなピクセルになります。", "zh": "将图像简化为色块。色块越多，马赛克越细；色块越少，像素越大。", "hi": "छवि को रंग के ब्लॉकों में बदल देता है। ज़्यादा ब्लॉक से बारीक मोज़ेक बनता है; कम ब्लॉक से बड़े पिक्सेल रह जाते हैं।", "id": "Mengurangi gambar menjadi blok-blok warna. Lebih banyak blok menghasilkan mosaik halus; lebih sedikit blok menyisakan piksel besar.", "ru": "Сводит изображение к цветным блокам. Больше блоков дают мелкую мозаику; меньше блоков оставляют крупные пиксели."},
  "Reels / TikTok": {"en": "Reels / TikTok", "es": "Reels / TikTok", "ar": "Reels / TikTok", "ko": "Reels / TikTok", "ja": "Reels / TikTok", "zh": "Reels / TikTok", "hi": "Reels / TikTok", "id": "Reels / TikTok", "ru": "Reels / TikTok"},
  "Referencia · nova recriacao Codex": {"en": "Reference · new Codex recreation", "es": "Referencia · nueva recreación Codex", "ar": "مرجع · إعادة إنشاء Codex جديدة", "ko": "레퍼런스 · 새 Codex 재구성", "ja": "リファレンス · 新しい Codex 再現", "zh": "参考 · 新的 Codex 重制", "hi": "संदर्भ · नया Codex पुनर्निर्माण", "id": "Referensi · rekreasi Codex baru", "ru": "Референс · новая реконструкция Codex"},
  "Reflect": {"en": "Reflect", "es": "Reflejar", "ar": "انعكاس", "ko": "반사", "ja": "反射", "zh": "反射", "hi": "परावर्तन", "id": "Refleksi", "ru": "Отражение"},
  "Reforça mais as cores pouco saturadas. Saturação age globalmente; proteção de pele reduz mudanças em tons quentes, de forma aproximada.": {"en": "Boosts less saturated colors more. Saturation acts globally; skin protection reduces changes in warm tones, approximately.", "es": "Refuerza más los colores poco saturados. Saturación actúa globalmente; protección de piel reduce los cambios en tonos cálidos, de forma aproximada.", "ar": "يقوّي الألوان قليلة التشبع أكثر. التشبع يعمل على الصورة كلها؛ حماية البشرة تقلل التغييرات في الدرجات الدافئة بشكل تقريبي.", "ko": "채도가 낮은 색상을 더 강하게 보강합니다. 채도는 전체에 작용하고, 피부 보호는 따뜻한 톤의 변화를 대략적으로 줄여 줍니다.", "ja": "彩度の低い色をより強く強調します。彩度は全体に作用し、肌の保護は暖色系の変化をおおまかに抑えます。", "zh": "更多地增强低饱和度的颜色。饱和度作用于全局；肤色保护会近似地减少暖色调的变化。", "hi": "कम संतृप्त रंगों को ज़्यादा मज़बूत करता है। संतृप्ति पूरी छवि पर काम करती है; त्वचा सुरक्षा गर्म टोन में बदलाव को लगभग कम कर देती है।", "id": "Memperkuat warna yang kurang jenuh lebih banyak. Saturasi bekerja secara global; perlindungan kulit mengurangi perubahan pada nada hangat, secara kira-kira.", "ru": "Сильнее усиливает малонасыщенные цвета. Насыщенность действует глобально; защита кожи приблизительно уменьшает изменения в тёплых тонах."},
  "Reinhard": {"en": "Reinhard", "es": "Reinhard", "ar": "Reinhard", "ko": "Reinhard", "ja": "Reinhard", "zh": "Reinhard", "hi": "Reinhard", "id": "Reinhard", "ru": "Reinhard"},
  "Reinhard 2": {"en": "Reinhard 2", "es": "Reinhard 2", "ar": "Reinhard 2", "ko": "Reinhard 2", "ja": "Reinhard 2", "zh": "Reinhard 2", "hi": "Reinhard 2", "id": "Reinhard 2", "ru": "Reinhard 2"},
  "RelativeFilename": {"en": "RelativeFilename", "es": "RelativeFilename", "ar": "RelativeFilename", "ko": "RelativeFilename", "ja": "RelativeFilename", "zh": "RelativeFilename", "hi": "RelativeFilename", "id": "RelativeFilename", "ru": "RelativeFilename"},
  "Remapeia preto, branco e gama. Primeiro ajuste os pontos de entrada; depois a gama dos meios-tons. Saída min/max limita o contraste final; canal isola R, G ou B.": {"en": "Remaps black, white and gamma. First adjust the input points; then the midtone gamma. Output min/max limits the final contrast; channel isolates R, G or B.", "es": "Reasigna negro, blanco y gamma. Primero ajusta los puntos de entrada; después la gamma de los medios tonos. Salida mín/máx limita el contraste final; canal aísla R, G o B.", "ar": "يعيد تعيين الأسود والأبيض والغاما. اضبط أولًا نقاط الإدخال، ثم غاما الدرجات الوسطى. الحد الأدنى/الأقصى للإخراج يحدّ من التباين النهائي؛ القناة تعزل R أو G أو B.", "ko": "검정, 흰색, 감마를 다시 매핑합니다. 먼저 입력 지점을 조정한 다음 중간톤 감마를 조정하세요. 출력 최소/최대는 최종 대비를 제한하고, 채널은 R, G, B를 분리합니다.", "ja": "黒、白、ガンマを再マッピングします。まず入力ポイントを調整し、次に中間調のガンマを調整します。出力の最小/最大は最終的なコントラストを制限し、チャンネルは R、G、B を個別に扱います。", "zh": "重新映射黑场、白场和灰度系数。先调整输入点，再调整中间调的灰度系数。输出最小/最大限制最终对比度；通道可单独处理 R、G 或 B。", "hi": "काला, सफ़ेद और गामा को फिर से मैप करता है। पहले इनपुट बिंदु समायोजित करें; फिर मिडटोन का गामा। आउटपुट न्यूनतम/अधिकतम अंतिम कंट्रास्ट को सीमित करता है; चैनल R, G या B को अलग करता है।", "id": "Memetakan ulang hitam, putih, dan gamma. Sesuaikan titik input dulu, lalu gamma nada tengah. Output min/maks membatasi kontras akhir; kanal memisahkan R, G, atau B.", "ru": "Переназначает чёрную и белую точки и гамму. Сначала настройте входные точки, затем гамму средних тонов. Выход мин/макс ограничивает итоговый контраст; канал выделяет R, G или B."},
  "Remove arquivos temporarios de preview e render": {"en": "Removes temporary preview and render files", "es": "Elimina archivos temporales de vista previa y render", "ar": "يزيل الملفات المؤقتة للمعاينة والعرض", "ko": "미리보기 및 렌더 임시 파일을 삭제합니다", "ja": "プレビューとレンダリングの一時ファイルを削除します", "zh": "删除预览和渲染的临时文件", "hi": "पूर्वावलोकन और रेंडर की अस्थायी फ़ाइलें हटाता है", "id": "Menghapus berkas sementara pratinjau dan render", "ru": "Удаляет временные файлы предпросмотра и рендера"},
  "remover cor": {"en": "remove color", "es": "quitar color", "ar": "إزالة اللون", "ko": "색상 제거", "ja": "色を除去", "zh": "去除颜色", "hi": "रंग हटाएँ", "id": "hapus warna", "ru": "удалить цвет"},
  "Repete a camada. Tile Width/Height e Output Width/Height são percentuais da entrada. Mirror Edges espelha repetições; Phase desloca linhas ou colunas.": {"en": "Repeats the layer. Tile Width/Height and Output Width/Height are percentages of the input. Mirror Edges mirrors repetitions; Phase shifts rows or columns.", "es": "Repite la capa. Tile Width/Height y Output Width/Height son porcentajes de la entrada. Mirror Edges refleja las repeticiones; Phase desplaza filas o columnas.", "ar": "يكرر الطبقة. Tile Width/Height و Output Width/Height نسب مئوية من الإدخال. Mirror Edges يعكس التكرارات؛ Phase يزيح الصفوف أو الأعمدة.", "ko": "레이어를 반복합니다. Tile Width/Height와 Output Width/Height는 입력 대비 백분율입니다. Mirror Edges는 반복을 거울처럼 뒤집고, Phase는 행이나 열을 이동합니다.", "ja": "レイヤーを繰り返します。Tile Width/Height と Output Width/Height は入力に対する割合です。Mirror Edges は繰り返しを鏡像にし、Phase は行または列をずらします。", "zh": "重复图层。Tile Width/Height 和 Output Width/Height 是相对输入的百分比。Mirror Edges 镜像重复部分；Phase 偏移行或列。", "hi": "लेयर को दोहराता है। Tile Width/Height और Output Width/Height इनपुट के प्रतिशत हैं। Mirror Edges दोहरावों को मिरर करता है; Phase पंक्तियों या स्तंभों को खिसकाता है।", "id": "Mengulang lapisan. Tile Width/Height dan Output Width/Height adalah persentase dari input. Mirror Edges mencerminkan pengulangan; Phase menggeser baris atau kolom.", "ru": "Повторяет слой. Tile Width/Height и Output Width/Height — проценты от входа. Mirror Edges зеркалит повторы; Phase сдвигает строки или столбцы."},
  "Repete a imagem no espaço, não no passado. Ajuste deslocamento, escala, rotação e decaimento por cópia.": {"en": "Repeats the image in space, not in the past. Adjust offset, scale, rotation and decay per copy.", "es": "Repite la imagen en el espacio, no en el pasado. Ajusta desplazamiento, escala, rotación y decaimiento por copia.", "ar": "يكرر الصورة في المكان، لا في الزمن الماضي. اضبط الإزاحة والمقياس والدوران والاضمحلال لكل نسخة.", "ko": "이미지를 과거가 아닌 공간에서 반복합니다. 복사본마다 오프셋, 배율, 회전, 감쇠를 조정하세요.", "ja": "画像を時間ではなく空間で繰り返します。コピーごとのオフセット、スケール、回転、減衰を調整します。", "zh": "在空间中而非时间上重复图像。可逐份调整偏移、缩放、旋转和衰减。", "hi": "छवि को समय में नहीं, स्थान में दोहराता है। हर प्रति के लिए ऑफ़सेट, स्केल, घुमाव और क्षय समायोजित करें।", "id": "Mengulang gambar di ruang, bukan di masa lalu. Sesuaikan pergeseran, skala, rotasi, dan peluruhan per salinan.", "ru": "Повторяет изображение в пространстве, а не во времени. Настройте смещение, масштаб, вращение и затухание для каждой копии."},
  "Repetir": {"en": "Repeat", "es": "Repetir", "ar": "تكرار", "ko": "반복", "ja": "繰り返し", "zh": "重复", "hi": "दोहराएँ", "id": "Ulangi", "ru": "Повтор"},
  "Respirar": {"en": "Breathe", "es": "Respirar", "ar": "تنفّس", "ko": "숨쉬기", "ja": "呼吸", "zh": "呼吸", "hi": "साँस", "id": "Bernapas", "ru": "Дыхание"},
  "Restart Noise": {"en": "Restart Noise", "es": "Reiniciar ruido", "ar": "إعادة تشغيل الضوضاء", "ko": "노이즈 재시작", "ja": "ノイズ再開", "zh": "重启噪波", "hi": "नॉइज़ रीस्टार्ट", "id": "Mulai ulang noise", "ru": "Перезапуск шума"},
  "Result": {"en": "Result", "es": "Resultado", "ar": "النتيجة", "ko": "결과", "ja": "結果", "zh": "结果", "hi": "परिणाम", "id": "Hasil", "ru": "Результат"},
  "Retangulo rapido": {"en": "Fast rectangle", "es": "Rectángulo rápido", "ar": "مستطيل سريع", "ko": "빠른 사각형", "ja": "高速の長方形", "zh": "快速矩形", "hi": "तेज़ आयत", "id": "Persegi panjang cepat", "ru": "Быстрый прямоугольник"},
  "Reto": {"en": "Straight", "es": "Recto", "ar": "مستقيم", "ko": "직선", "ja": "直線", "zh": "直线", "hi": "सीधा", "id": "Lurus", "ru": "Прямой"},
  "Revela ou recorta a camada em faixas. Conclusao vai de imagem completa a transparente; direcao, faixas e suavidade controlam o recorte.": {"en": "Reveals or cuts the layer in strips. Completion goes from full image to transparent; direction, strips and softness control the cut.", "es": "Revela o recorta la capa en franjas. Finalización va de imagen completa a transparente; dirección, franjas y suavidad controlan el recorte.", "ar": "يكشف الطبقة أو يقصّها على شكل شرائط. الاكتمال يتدرج من الصورة الكاملة إلى الشفافية؛ الاتجاه والشرائط والنعومة تتحكم في القص.", "ko": "레이어를 띠 모양으로 드러내거나 잘라냅니다. 완료는 전체 이미지에서 투명까지 진행되며, 방향, 띠, 부드러움이 잘림을 제어합니다.", "ja": "レイヤーを帯状に表示または切り抜きます。完了は画像全体から透明までを変化させ、方向、帯、柔らかさで切り抜きを制御します。", "zh": "以条纹显示或裁切图层。完成度从完整图像到透明；方向、条纹数和柔和度控制裁切。", "hi": "लेयर को पट्टियों में प्रकट या काटता है। पूर्णता पूरी छवि से पारदर्शी तक जाती है; दिशा, पट्टियाँ और कोमलता कटाव को नियंत्रित करती हैं।", "id": "Menampilkan atau memotong lapisan dalam garis-garis. Penyelesaian berjalan dari gambar penuh ke transparan; arah, garis, dan kehalusan mengatur potongan.", "ru": "Открывает или вырезает слой полосами. Завершение идёт от полного изображения к прозрачности; направление, полосы и мягкость управляют вырезом."},
