  "Suavidade externa": {"en": "Outer softness", "es": "Suavidad exterior", "ar": "نعومة خارجية", "ko": "외부 부드러움", "ja": "外側の柔らかさ", "zh": "外部柔和度", "hi": "बाहरी कोमलता", "id": "Kehalusan luar", "ru": "Внешняя мягкость"},
