  "Superfície inclinada": {"en": "Tilted surface", "es": "Superficie inclinada", "ar": "سطح مائل", "ko": "기울어진 표면", "ja": "傾いた面", "zh": "倾斜表面", "hi": "झुकी हुई सतह", "id": "Permukaan miring", "ru": "Наклонная поверхность"},
  "Suspensao · poeira mineral": {"en": "Suspension · mineral dust", "es": "Suspensión · polvo mineral", "ar": "معلّق · غبار معدني", "ko": "부유물 · 광물 먼지", "ja": "浮遊 · 鉱物の塵", "zh": "悬浮 · 矿物尘埃", "hi": "निलंबन · खनिज धूल", "id": "Suspensi · debu mineral", "ru": "Взвесь · минеральная пыль"},
