  "Glitch Slices": {"en": "Glitch Slices", "es": "Franjas glitch", "ar": "شرائح غليتش", "ko": "글리치 슬라이스", "ja": "グリッチスライス", "zh": "故障切片", "hi": "ग्लिच स्लाइस", "id": "Irisan glitch", "ru": "Глитч-срезы"},
  "Posterize Time": {"en": "Posterize Time", "es": "Posterizar tiempo", "ar": "تقطيع الزمن", "ko": "시간 포스터화", "ja": "ポスタリゼーション時間", "zh": "色调分离时间", "hi": "पोस्टराइज़ टाइम", "id": "Posterisasi Waktu", "ru": "Постеризация времени"},
