  "Vintage quente": {"en": "Warm vintage", "es": "Vintage cálido", "ar": "عتيق دافئ", "ko": "따뜻한 빈티지", "ja": "暖かいビンテージ", "zh": "暖调复古", "hi": "गर्म विंटेज", "id": "Vintage hangat", "ru": "Тёплый винтаж"},
  "Escuro contrastado": {"en": "Dark contrast", "es": "Oscuro contrastado", "ar": "داكن متباين", "ko": "어두운 대비", "ja": "ダークコントラスト", "zh": "暗调高对比", "hi": "गहरा कंट्रास्ट", "id": "Gelap kontras", "ru": "Тёмный контраст"},
  "PSD suave": {"en": "Soft PSD", "es": "PSD suave", "ar": "PSD ناعم", "ko": "부드러운 PSD", "ja": "ソフトPSD", "zh": "柔和PSD", "hi": "सॉफ्ट PSD", "id": "PSD lembut", "ru": "Мягкий PSD"},
  "Bleach bypass": {"en": "Bleach bypass", "es": "Bleach bypass", "ar": "تجاوز التبييض", "ko": "블리치 바이패스", "ja": "ブリーチバイパス", "zh": "跳漂白", "hi": "ब्लीच बाईपास", "id": "Bleach bypass", "ru": "Отбеливание"},
