  "Desfoque da mascara": {"en": "Mask Blur", "es": "Desenfoque de la máscara", "ar": "تمويه القناع", "ko": "마스크 흐림", "ja": "マスクのぼかし", "zh": "蒙版模糊", "hi": "मास्क का धुंधलापन", "id": "Buram masker", "ru": "Размытие маски"},
  "Inverter mascara": {"en": "Invert Mask", "es": "Invertir máscara", "ar": "عكس القناع", "ko": "마스크 반전", "ja": "マスクを反転", "zh": "反转蒙版", "hi": "मास्क उलटें", "id": "Balik masker", "ru": "Инвертировать маску"},
  "Minimo": {"en": "Minimum", "es": "Mínimo", "ar": "الحد الأدنى", "ko": "최소", "ja": "最小", "zh": "最小值", "hi": "न्यूनतम", "id": "Minimum", "ru": "Минимум"},
